  bob: { speed: 15, amount: 0.1, unit: 'm', max: 10, steps: [0.02, 0.05, 0.1, 0.2, 0.3, 0.5, 1, 2], word: 'Bob', does: 'bobs', one: 'bob', many: 'bobs' },
