// the page's listeners: files dropped anywhere on the studio's page (the Upload pane opens with them), the file choosers,
// the new scene's name as it is typed
function uploadBind() {
  const ex = $('#explore'), over = ev => !!(ev.dataTransfer && [...(ev.dataTransfer.types || [])].includes('Files'));
  const zone = on => document.querySelectorAll('#explore .stu-drop').forEach(z => z.classList.toggle('hot', on));
  document.addEventListener('dragover', ev => { if (!over(ev) || XR.on || OPT.visit || UP.busy) return; ev.preventDefault(); ev.dataTransfer.dropEffect = 'copy'; zone(true); });
  document.addEventListener('dragleave', ev => { if (!ev.relatedTarget) zone(false); });
  document.addEventListener('drop', ev => {
    if (!over(ev) || XR.on || OPT.visit) return;
    ev.preventDefault(); zone(false);
    if (UP.busy) return;
    // (pictures dropped onto a model's row: that model's)
    const li = ev.target && ev.target.closest && ev.target.closest('.stu-plan li[data-row]'), fl = [...((ev.dataTransfer && ev.dataTransfer.files) || [])];
    if (li && fl.length && fl.every(f => CONV.IM.isPicture(f.name))) { upGive(+li.dataset.row, fl); return; }
    if (APP.mode !== 'explore') APP.enterExplore();
    readDropped(ev.dataTransfer).then(upTake);
  });
  ex.addEventListener('input', ev => {
    if (ev.target.id === 'stuNewName') { UP.newName = ev.target.value; const b = ex.querySelector('[data-act="up:make"]'); if (b) b.disabled = UP.making || !UP.newName.trim(); }
    if (ev.target.id === 'stuSceneName') { NS.name = ev.target.value; const b = ex.querySelector('[data-act="scenemake"]'); if (b) b.disabled = NS.making || !NS.name.trim(); }   // (the Scene pane's New scene)
  });
  ex.addEventListener('keydown', ev => {
    if (ev.target.id === 'stuNewName' && ev.key === 'Enter') { ev.preventDefault(); upMake(); }
    if (ev.target.id === 'stuSceneName' && ev.key === 'Enter') { ev.preventDefault(); sceneMake(NS.name); }
  });
  ex.addEventListener('change', ev => {
    const t = ev.target;
    if (t.id !== 'stuFiles' && t.id !== 'stuFolder') return;
    const list = [...(t.files || [])].map(f => ({ path: f.webkitRelativePath || f.name, file: f }));
    t.value = '';
    if (list.length) upTake(list);
  });
}
const UP_ACT = {
  'up:scene': v => upPick(v),
  'up:new': () => { UP.newOpen = !UP.newOpen; UP.newNote = ''; if (UP.newOpen) later(() => { const i = $('#stuNewName'); if (i) i.focus(); }, 50); },
  'up:make': () => upMake(),
  'up:choose': () => { const i = $('#stuFiles'); if (i) i.click(); },
  'up:folder': () => { const i = $('#stuFolder'); if (i) i.click(); },
  'up:quest': () => { UP.quest = !UP.quest; upChanged(); },
  'up:replace': () => { UP.replace = !UP.replace; upNames(); upChanged(); },
  'up:run': () => upRun(),
  'up:pv': v => upPreview(+v),   // (a model's picture with its share kept: e7d_lite.js)
  'up:clear': () => upClear(),
  'up:open': () => upOpen(),
  'up:use': v => { const [ri, n, q] = JSON.parse(v), r = UP.rows[ri], x = r && r.names.find(y => y.name === n), e = UP.entries.find(y => y.path === q); if (x && e && r.state === 'plan') { Object.assign(x, { entry: e, how: 'chosen' }); upRebuild(); upChanged(); } },
  'up:unuse': v => { const [ri, n] = JSON.parse(v), r = UP.rows[ri], x = r && r.names.find(y => y.name === n); if (x && r.state === 'plan') { Object.assign(x, { entry: null, how: '' }); upRebuild(); upChanged(); } },
  'up:file': v => { const [ri, n] = JSON.parse(v); chooseTex({ kind: 'up', ri, name: n }); },
  'up:slot': v => { const [ri, i] = JSON.parse(v), a = UP.rows[ri] && UP.rows[ri].adds[i]; if (a) { a.slot = SLOTS_ADD[(SLOTS_ADD.indexOf(a.slot) + 1) % SLOTS_ADD.length]; upChanged(); } },
  'up:unadd': v => { const [ri, i] = JSON.parse(v), r = UP.rows[ri]; if (r && r.adds[i] && r.state === 'plan') { r.adds.splice(i, 1); upRebuild(); upChanged(); } },
};
// ============================================================== R2 (direct) ==
// A relay that keeps its scenes in a Cloudflare R2 bucket (relay/README.md, "Scenes in Cloudflare R2") says so in its list
// of scenes (linkTtl, and direct: true while the bucket takes its upload links). Its listing of a scene gives each file a
// signed link, which fileUrl hands the loaders and the sound elements: the page fetches the file straight from the
// bucket, from its own origin (no password in it: the link is the permission, for that one file, until it lapses). Those
// links live linkTtl seconds (R2_LINK_TTL, 12 hours by default) from the listing that gave them, so the listing is read
// again once half of that has passed by the wall clock (a device asleep meanwhile, such as a headset taken off, reads it
// as it wakes: looked at every minute, when the page shows again, before a file is fetched, and once more after a link
// the bucket refused: linksFresh, linksAgain). An upload goes straight into the bucket too: upSend hands a .../file
// upload to upDirect, which asks the relay for a signed PUT (.../put, with the file's size), sends the file there with
// its progress, and tells the relay it is there (.../done). The relay answers as for an upload through it ({ ok, path,
// bytes, at }; 409 for a name taken), so the Upload pane, Convert to GLB and the texture buttons work the same either
// way. Should the bucket refuse the PUT (its CORS rule missing, a signed header it will not take) the file goes through
// the relay instead, and so does every upload after it on this page (directOff).
let linksT = 0, linksJob = null, directOff = false;
const linksAge = () => Date.now() - (SRC.linksAt || 0);
const linksOld = () => SRC.linkTtl > 0 && STU.files.some(f => f.url) && linksAge() > SRC.linkTtl * 500;
// the listing just read (no ms) starts the watch over its links' age; ms: look again then
function linksSoon(ms) {
  unlater(linksT); linksT = 0;
  if (!(SRC.linkTtl > 0)) return;
  if (!ms) SRC.linksAt = Date.now();
  linksT = later(() => { linksT = 0; if (linksOld()) linksFresh(); else linksSoon(Math.min(60, SRC.linkTtl / 4) * 1000); }, ms || Math.min(60, SRC.linkTtl / 4) * 1000);
}
// the listing read again now (one at a time); a listing that cannot be read is asked again a minute later
function linksFresh() {
  if (!linksJob) {
    linksJob = refreshFiles(new Set()).finally(() => { linksJob = null; if (linksOld()) linksSoon(60000); });
  }
  return linksJob;
}
// a signed link this page holds: the same file's link after reading the listing again (null: no other one came)
async function linksAgain(url) {
  const f = STU.files.find(x => x.url === url) || [...PV.files.values()].find(x => x.url === url);   // (a model's picture too)
  if (!f) return null;
  await linksFresh();
  const g = STU.fileMap.get(f.path) || PV.files.get(f.path);
  return g && g.url && g.url !== url ? g.url : null;
}
// (the page shown again after a while: links that lapsed meanwhile read again at once)
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible' && linksOld()) linksFresh(); });

// one upload straight into the bucket: url is the .../file address upSend was given (its scene, path and replace=1)
async function upDirect(url, body, onP) {
  if (!SRC.direct || directOff) return upVia(url, body, onP);
  const u = new URL(url, location.href), m = /\/api\/scenes\/([^/]+)\/file$/.exec(u.pathname);
  if (!m || SRC.held) throw SRC.held ? AUTH_ERR() : new Error('not an upload');
  const q = new URLSearchParams(u.search), size = body ? (body.size !== undefined ? body.size : body.byteLength || 0) : 0;
  const api = what => `${SRC.base}/api/scenes/${m[1]}/${what}?path=${encodeURIComponent(q.get('path') || '')}${q.get('replace') === '1' ? '&replace=1' : ''}&size=${size}`;
  let link;
  try { link = await getJSON(api('put'), { method: 'POST' }); } catch (e) {
    if (e.status !== 501) throw e;
    return through(url, body, onP, 'the relay gives no upload links now');
  }
  const st = await new Promise(res => {
    const x = new XMLHttpRequest();
    x.open('PUT', link.url);
    for (const [k, v] of Object.entries((link && link.headers) || {})) x.setRequestHeader(k, v);
    if (onP) x.upload.onprogress = e => { if (e.lengthComputable) onP(e.loaded / Math.max(1, e.total)); };
    x.onload = () => res(x.status);
    x.onerror = () => res(0);
    x.send(body || null);
  });
  // (412, or 409 as R2 may say: a file of that name came meanwhile, as the relay's 409)
  if (st === 412 || st === 409) throw Object.assign(new Error('there is a file by that name'), { status: 409 });
  if (st < 200 || st >= 300) {
    // (not reached (0: the bucket's CORS rule is the likely cause), or refused (400, 403, 501): through the relay)
    if (st === 0 || st === 400 || st === 403 || st === 501) return through(url, body, onP, st ? `the bucket refused it (HTTP ${st})` : 'the bucket could not be reached (is its CORS rule in place? the relay\'s start log says)');
    throw Object.assign(new Error('the scenes\' storage refused it (HTTP ' + st + ')'), { status: st });
  }
  return getJSON(api('done'), { method: 'POST' });
}
// the upload sent through the relay after the bucket refused it, and every one after it on this page
function through(url, body, onP, why) {
  directOff = true;
  console.warn(`The studio sends its uploads through the relay from now on: ${why}.`);
  return upVia(url, body, onP);
}
// through the relay, waiting while it has as many uploads on their way as it takes at once (429)
async function upVia(url, body, onP) {
  for (let k = 0; ; k++) {
    try { return await upPost(url, body, onP); } catch (e) {
      if (e.status !== 429 || k > 8) throw e;
      await new Promise(res => later(res, 1000 * Math.max(2, e.retry || 3)));
    }
  }
}
// ======================================================== FEWER TRIANGLES ==
// An object's card, page and headset alike (tools/studio/SPEC.md, "Fewer triangles" and "Change texture"; the owner, 6
// November 2026: "models need to be way less triangles", "a percentage ... adjustable per model with a preview", "20
// percent by default for everything", "preview in ar/vr would really be helpful", and "a change texture button on models
// placed in the scene").
// Fewer triangles: a share of its triangles kept (2 to 100 %, 20 % to start), shown at once in place on this device only
// (the object's own model given the lighter geometry by the converter's reduce; nothing shared until saved; Cancel puts it
// back); Save makes models/<name>.glb as Convert to GLB does (made again from the original a GLB stands for, when the
// scene has it, else from itself, the old one kept under originals/; every object of that file switched where it stands,
// one Undo step, for everyone at a station). The share is of what Save makes it from, so a model made too light comes
// back up from its original; the preview shows at most what the model placed has.
// Change texture: a material, a slot and a picture of the scene (or, on a page, one from this computer), shown at once on
// this device; Save bakes it into the model's GLB (texGo: asset.extras.studio.tex records it, objects switched where they
// stand); Cancel puts it back. Both save from a headset too, with a relay that takes uploads. Never in the layout or
// collab.state(): what is shared is the switch to the GLB, as for Convert to GLB.
const FT_DEFAULT = 0.2, FT_PICKS = [0.1, 0.2, 0.5];
const FT = { id: '', keep: FT_DEFAULT, pv: null, busy: false, gen: 0, t: 0, note: '', noteC: 'muted', saving: false, after: 0, fill: null, fsw: [], fLight: '' };
const CT = { id: '', mat: 0, slot: 'map', pic: null, tex: null, saved: null, busy: false, gen: 0, note: '', noteC: 'muted', page: 0, saving: false, after: 0, light: '', model: null };
const CT_SLOTS = ['map', 'normalMap', 'roughnessMap', 'metalnessMap', 'aoMap', 'emissiveMap', 'alphaMap'];
const pct = v => (v * 100 >= 10 || v === 0 ? Math.round(v * 100) : +(v * 100).toPrecision(2)) + ' %';
// an object these work on: a model of the scene, in, editing on (never a visitor's kiosk)
const canLite = it => !!(it && it.kind === 'o' && editOn() && !OPT.visit && it.model && it.E && it.E.state === 'ready' && it.E.info && STU.fileMap.has(it.rec.file) && MODEL_EXT.includes(extOf(it.rec.file)));
